// Sailing race track map. Generated by make_sailing_map.py; data in tracks.json.
function startApp(D) {
const TRACKS = D.tracks;
const MARKS = D.marks, LINES = D.lines, START_LINE = D.startLine, MARK_TOL = D.markTol, START_EXCLUDE = D.startExclude;
if (D.homeUrl) { const a = document.getElementById("home"); a.href = D.homeUrl; a.hidden = false; }
const PRE_GREY = "#8a8a8a";
const CATEGORICAL = ["#e6194b","#3cb44b","#4363d8","#f58231","#911eb4","#42d4f4","#f032e6","#9a6324",
                     "#000075","#808000","#800000","#469990","#dcbeff","#aaffc3","#ffd8b1","#bfef45"];
// Sequential ramp chosen to stay visible on the light chart (no pale yellow end).
const RAMP = ["#2b3a9e","#1f8fd1","#21b39b","#7cc242","#f2a20c","#e8481f","#9e0a4f"];
const MODES = {
  solid: { label: "Solid" },
  time:  { label: "Time since start", unit: "min", get: (t, i) => t.t[i] / 60, fmt: v => v.toFixed(0) },
  speed: { label: "Speed", unit: "kn", get: (t, i) => t.s[i] / 10, fmt: v => v.toFixed(1) },
  hr:    { label: "Heart rate", unit: "bpm", get: (t, i) => t.h[i] || null, fmt: v => v.toFixed(0) },
};
const BINS = 48;

TRACKS.forEach((t, k) => { t.id = k; t.year = t.date.slice(0, 4); t.ll = t.la.map((a, i) => [a / 1e5, t.lo[i] / 1e5]); });
const years = [...new Set(TRACKS.map(t => t.year))].sort();

// ---- map + layers ----------------------------------------------------------
const map = L.map("map", { preferCanvas: true });
const ocean = L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/Ocean/World_Ocean_Base/MapServer/tile/{z}/{y}/{x}",
  { maxZoom: 18, maxNativeZoom: 16, attribution: "Esri, GEBCO, NOAA" });
const osm = L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
  { maxZoom: 19, attribution: "&copy; OpenStreetMap contributors" });
const noaa = L.tileLayer.wms(
  "https://gis.charttools.noaa.gov/arcgis/rest/services/MCS/NOAAChartDisplay/MapServer/exts/MaritimeChartService/WMSServer",
  { layers: "0,1,2,3,4,5,6,7", format: "image/png", transparent: true, version: "1.3.0",
    maxZoom: 19, attribution: "NOAA Office of Coast Survey ENC" });
const seamarks = L.tileLayer("https://tiles.openseamap.org/seamark/{z}/{x}/{y}.png",
  { maxZoom: 18, attribution: "OpenSeaMap" });
ocean.addTo(map); noaa.addTo(map);
const layersCtl = L.control.layers({ "Esri Ocean": ocean, "OpenStreetMap": osm },
                 { "NOAA nautical chart (ENC)": noaa, "OpenSeaMap seamarks": seamarks },
                 { position: "topleft" }).addTo(map);
L.control.scale({ imperial: true, metric: true }).addTo(map);

map.createPane("prestart").style.zIndex = 390;
const preRenderer = L.canvas({ pane: "prestart" });
const trackLayer = L.layerGroup().addTo(map);
const hoverDot = L.circleMarker([0, 0], { radius: 6, color: "#000", weight: 2, fillColor: "#fff", fillOpacity: 1,
                                          interactive: false });

const marks = L.layerGroup().addTo(map);
LINES.forEach(([name, a, b]) => {
  L.polyline([MARKS[a], MARKS[b]], { color: "#000", weight: 3, dashArray: "6 5" })
    .bindTooltip(`${name} (${a}–${b})`, { sticky: true }).addTo(marks);
});
Object.entries(MARKS).forEach(([name, ll]) => {
  L.circleMarker(ll, { radius: 6, color: "#000", weight: 2, fillColor: "#ff8c00", fillOpacity: 1 })
    .bindTooltip(name, { permanent: true, direction: "right", offset: [6, 0], className: "mark-label" })
    .bindPopup(`<b>${name}</b><br>${ll[0].toFixed(5)}, ${ll[1].toFixed(5)}`)
    .addTo(marks);
});
layersCtl.addOverlay(marks, "Racing marks");

// ---- helpers ---------------------------------------------------------------
const hex = c => [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16));
function rampColor(f) {
  f = Math.min(1, Math.max(0, f)) * (RAMP.length - 1);
  const i = Math.min(RAMP.length - 2, Math.floor(f)), a = hex(RAMP[i]), b = hex(RAMP[i + 1]), u = f - i;
  return `rgb(${a.map((v, k) => Math.round(v + (b[k] - v) * u)).join(",")})`;
}
const pad = n => String(n).padStart(2, "0");
const fmtDur = s => `${Math.floor(s / 3600)}:${pad(Math.floor(s % 3600 / 60))}`;
const fmtClock = s => { const a = Math.abs(Math.round(s)); return `${s < 0 ? "−" : "+"}${Math.floor(a / 60)}:${pad(a % 60)}`; };
const nice = d => new Date(d + "T12:00:00").toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
function quantile(sorted, q) { return sorted.length ? sorted[Math.min(sorted.length - 1, Math.floor(q * sorted.length))] : 0; }

// ---- wind ------------------------------------------------------------------
const WIND = D.wind;   // station info, or null when no wind data was built in
const COMPASS = ["N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"];
const dirName = d => COMPASS[Math.round(d / 22.5) % 16];
function windAt(t, sec) {   // nearest observation within 6 minutes
  let best = null;
  t.w.forEach(o => { if (Math.abs(o[0] - sec) <= 360 && (!best || Math.abs(o[0] - sec) < Math.abs(best[0] - sec))) best = o; });
  return best;
}
function windMean(t, a = 0, b = t.dur) {   // mean speed, vector-mean direction, max gust over [a, b]
  const os = t.w.filter(o => o[0] >= a - 180 && o[0] <= b + 180);
  if (!os.length) return null;
  let x = 0, y = 0;
  os.forEach(o => { x += Math.sin(o[3] * Math.PI / 180); y += Math.cos(o[3] * Math.PI / 180); });
  return { kn: os.reduce((s, o) => s + o[1], 0) / os.length / 10, gust: Math.max(...os.map(o => o[2])) / 10,
           dir: (Math.atan2(x, y) * 180 / Math.PI + 360) % 360 };
}
const windText = m => `${m.kn.toFixed(1)} kn from ${dirName(m.dir)} (${Math.round(m.dir)}°)`;

let windCursor = null;   // updates the cursor line on the wind chart
function drawWindChart(t) {
  const box = document.getElementById("wind");
  windCursor = null;
  if (!t || !t.w.length) { box.innerHTML = ""; return; }
  const W = 256, H = 112, ml = 22, mr = 4, mt = 18, mb = 18;
  const x0 = Math.min(-300, t.w[0][0]), x1 = Math.max(t.dur + 300, 600);
  const top = Math.max(10, Math.ceil(Math.max(...t.w.map(o => o[2])) / 10 / 5) * 5);
  const X = s => ml + (s - x0) / (x1 - x0) * (W - ml - mr), Y = k => mt + (1 - k / top) * (H - mt - mb);
  const css = getComputedStyle(document.documentElement), c1 = css.getPropertyValue("--series-1"),
        grid = css.getPropertyValue("--grid");
  const ws = t.w.filter(o => o[0] >= x0 && o[0] <= x1);
  const path = k => ws.map((o, i) => `${i ? "L" : "M"}${X(o[0]).toFixed(1)},${Y(o[k] / 10).toFixed(1)}`).join("");
  let svg = `<svg viewBox="0 0 ${W} ${H}" id="windSvg">`;
  for (let v = 0; v <= top; v += 5)
    svg += `<line x1="${ml}" x2="${W - mr}" y1="${Y(v)}" y2="${Y(v)}" stroke="${grid}"/><text x="${ml - 4}" y="${Y(v) + 3}" text-anchor="end">${v}</text>`;
  [[0, "start"], [t.dur, t.fin ? "finish" : "end"]].forEach(([s, lab]) =>
    svg += `<line x1="${X(s)}" x2="${X(s)}" y1="${mt - 2}" y2="${Y(0)}" stroke="currentColor" stroke-opacity=".45" stroke-dasharray="3 3"/>`
         + `<text x="${X(s)}" y="${H - 5}" text-anchor="middle">${lab}</text>`);
  svg += `<path d="${path(2)}" fill="none" stroke="${c1}" stroke-width="1.5" stroke-dasharray="4 3" stroke-opacity=".6"/>`
       + `<path d="${path(1)}" fill="none" stroke="${c1}" stroke-width="2"/>`;
  // direction arrows along the top, pointing where the wind blows to
  ws.forEach((o, i) => { if (i % 2) return;
    svg += `<g transform="translate(${X(o[0])},${mt - 9}) rotate(${o[3] + 180})"><path d="M0,6 L0,-5 M-3,-2 L0,-6 L3,-2" fill="none"
             stroke="currentColor" stroke-opacity=".6" stroke-width="1.3" stroke-linecap="round"/></g>`; });
  svg += `<line id="windCur" x1="0" x2="0" y1="${mt - 2}" y2="${Y(0)}" stroke="currentColor" stroke-opacity="0" />`
       + `<rect id="windHit" x="${ml}" y="0" width="${W - ml - mr}" height="${H}" fill="transparent"/></svg>`;
  const m = windMean(t);
  box.innerHTML = `<div class="head"><span><b style="color:var(--fg)">Wind</b> (kn)</span><span><i></i>speed</span>
    <span><i class="gust"></i>gust</span><span style="margin-left:auto">↑ blowing toward</span></div>${svg}`;
  const cur = box.querySelector("#windCur"), svgEl = box.querySelector("svg");
  windCursor = sec => {
    if (sec == null) { cur.setAttribute("stroke-opacity", 0); return; }
    cur.setAttribute("x1", X(sec)); cur.setAttribute("x2", X(sec)); cur.setAttribute("stroke-opacity", .7);
  };
  box.querySelector("#windHit").onmousemove = e => {
    const r = svgEl.getBoundingClientRect(), sec = x0 + ((e.clientX - r.left) / r.width * W - ml) / (W - ml - mr) * (x1 - x0);
    const o = windAt(t, sec);
    windCursor(o ? o[0] : null);
    if (!o) return;
    tip.innerHTML = `<b>${fmtClock(o[0])}</b> from gun<br>${(o[1] / 10).toFixed(1)} kn, gust ${(o[2] / 10).toFixed(1)} kn<br>from ${dirName(o[3])} (${o[3]}°)`;
    tip.style.display = "block";
    tip.style.left = Math.min(e.clientX + 12, innerWidth - 250) + "px"; tip.style.top = (e.clientY - 10) + "px";
  };
  box.querySelector("#windHit").onmouseleave = () => { tip.style.display = "none"; windCursor(null); };
}

// Map arrow at the wind station for the shown race's mean wind
const windArrow = WIND ? L.marker([WIND.lat, WIND.lon], { interactive: true, keyboard: false }) : null;
function drawWindArrow(t) {
  if (!windArrow) return;
  const m = t && windMean(t);
  if (!m) { map.removeLayer(windArrow); return; }
  windArrow.setIcon(L.divIcon({ className: "wind-icon", iconSize: [0, 0], html:
    `<div><svg viewBox="-30 -30 60 60" width="60" height="60"><g transform="rotate(${m.dir + 180})">
       <path d="M0,24 L0,-16" stroke="#1f5fbf" stroke-width="4" stroke-linecap="round"/>
       <path d="M-9,-8 L0,-22 L9,-8 Z" fill="#1f5fbf"/></g></svg></div><span>${m.kn.toFixed(0)} kn ${dirName(m.dir)}</span>` }))
    .bindTooltip(`Mean wind during the race: ${windText(m)}, gusts to ${m.gust.toFixed(0)} kn<br>NOAA ${WIND.id} ${WIND.name} (Stearns Wharf)`)
    .addTo(map);
}

// ---- start analysis --------------------------------------------------------
const [SA, SB] = START_LINE || ["G", "F"];
const LINE_M = map.distance(MARKS[SA], MARKS[SB]);
const fmtStart = s => {
  const a = Math.abs(s), txt = a < 60 ? `${Math.round(a)} s` : `${Math.floor(a / 60)}:${pad(Math.round(a % 60))}`;
  return s < 0 ? `−${txt} (early)` : `+${txt}`;
};
const posText = u => u < 0 ? `${Math.round(-u * LINE_M)} m outside ${SA}` : u > 1 ? `${Math.round((u - 1) * LINE_M)} m outside ${SB}`
                                                                               : `${Math.round(u * LINE_M)} m from ${SA}`;
// Start analysis: races from START_EXCLUDE years are left out (their start line/time differed).
const ANALYSED = TRACKS.filter(t => !START_EXCLUDE.includes(t.year));
const STARTED = ANALYSED.filter(t => t.st && t.st.ok), MISSED = ANALYSED.filter(t => t.st && !t.st.ok);
const TIME_EDGES = [-Infinity, ...Array.from({ length: 19 }, (_, i) => -60 + 10 * i), Infinity];   // 10 s bins, -60..120
const POS_EDGES = [-Infinity, ...Array.from({ length: 11 }, (_, i) => i / 10), Infinity];          // tenths of the line
const binOf = (edges, v) => { for (let i = 0; i < edges.length - 1; i++) if (v < edges[i + 1]) return i; return edges.length - 2; };
const tip = document.getElementById("tip");

function drawHist(svg, edges, value, binLabel, ticks, refs) {
  const W = 360, H = 124, ml = 26, mr = 4, mt = 14, mb = 22, n = edges.length - 1;
  const all = Array.from({ length: n }, () => []), sh = Array.from({ length: n }, () => []);
  const shownIds = new Set(shown.map(t => t.id));
  STARTED.forEach(t => { const b = binOf(edges, value(t)); all[b].push(t); if (shownIds.has(t.id)) sh[b].push(t); });
  const max = Math.max(1, ...all.map(a => a.length));
  const step = max > 20 ? 10 : max > 8 ? 5 : 2, top = Math.ceil(max / step) * step;
  const bw = (W - ml - mr) / n, y = v => mt + (H - mt - mb) * (1 - v / top);
  const css = getComputedStyle(document.documentElement), c1 = css.getPropertyValue("--series-1"),
        c2 = css.getPropertyValue("--series-2"), grid = css.getPropertyValue("--grid");
  const bar = (x, y0, y1, color) => {  // 4px rounded top anchored to the baseline
    const h = y1 - y0, w = bw - 2, r = Math.min(4, h, w / 2);
    if (h <= 0) return "";
    return `<path fill="${color}" d="M${x},${y1} V${y0 + r} Q${x},${y0} ${x + r},${y0} H${x + w - r} Q${x + w},${y0} ${x + w},${y0 + r} V${y1} Z"/>`;
  };
  let out = `<svg viewBox="0 0 ${W} ${H}">`;
  for (let v = 0; v <= top; v += step)
    out += `<line x1="${ml}" x2="${W - mr}" y1="${y(v)}" y2="${y(v)}" stroke="${grid}"/><text x="${ml - 4}" y="${y(v) + 3}" text-anchor="end">${v}</text>`;
  all.forEach((a, i) => {
    const x = ml + i * bw + 1;
    out += `<g class="col" data-i="${i}"><rect class="hit" x="${x - 1}" y="${mt}" width="${bw}" height="${H - mt - mb}" fill="transparent"/>`
         + bar(x, y(a.length), y(0), c1) + (sh[i].length && sh[i].length < a.length ? bar(x, y(sh[i].length), y(0), c2) : "")
         + (sh[i].length && sh[i].length === a.length ? bar(x, y(a.length), y(0), c2) : "") + `</g>`;
  });
  out += `<line x1="${ml}" x2="${W - mr}" y1="${y(0)}" y2="${y(0)}" stroke="currentColor" stroke-opacity=".35"/>`;
  // Reference lines (the gun, the marks)
  refs.forEach(pos => out += `<line x1="${ml + pos * bw}" x2="${ml + pos * bw}" y1="${mt - 4}" y2="${y(0)}" stroke="currentColor"
                                   stroke-opacity=".45" stroke-dasharray="3 3"/>`);
  // A single shown race gets a pointer above its bar.
  if (shown.length === 1) sh.forEach((a, i) => { if (!a.length) return;
    const cx = ml + (i + .5) * bw, cy = y(all[i].length) - 3;
    out += `<path d="M${cx - 5},${cy - 7} H${cx + 5} L${cx},${cy} Z" fill="${c2}"/>`; });
  ticks.forEach(([pos, label]) => {
    const x = ml + pos * bw;
    out += `<line x1="${x}" x2="${x}" y1="${y(0)}" y2="${y(0) + 4}" stroke="currentColor" stroke-opacity=".35"/>`
         + `<text x="${x}" y="${y(0) + 14}" text-anchor="middle">${label}</text>`;
  });
  svg.innerHTML = out + "</svg>";
  svg.querySelectorAll(".col").forEach(g => {
    const i = +g.dataset.i;
    g.onmousemove = e => {
      const names = sh[i].length && sh[i].length <= 6 ? `<br>${sh[i].map(t => nice(t.date)).join("<br>")}` : "";
      tip.innerHTML = `<b>${binLabel(i)}</b><br>${all[i].length} race${all[i].length === 1 ? "" : "s"}`
                    + (sh[i].length ? ` · ${sh[i].length} shown${names}` : "");
      tip.style.display = "block";
      tip.style.left = Math.min(e.clientX + 12, innerWidth - 250) + "px"; tip.style.top = (e.clientY - 10) + "px";
    };
    g.onmouseleave = () => tip.style.display = "none";
    // Clicking a bar with exactly one shown race... or one race in total: show that race.
    g.onclick = () => { if (all[i].length === 1) { sel.value = "t" + all[i][0].id; render(true); } };
  });
}

function drawStarts() {
  if (!document.getElementById("starts").classList.contains("open")) return;
  const ts = STARTED.map(t => t.st.t).sort((a, b) => a - b), us = STARTED.map(t => t.st.u).sort((a, b) => a - b);
  const early = ts.filter(v => v < 0).length, outside = us.filter(u => u < 0 || u > 1).length;
  document.getElementById("startStats").innerHTML =
    `${STARTED.length} of ${ANALYSED.length} races${START_EXCLUDE.length ? ` (excl. ${START_EXCLUDE.join(", ")})` : ""} · ${MISSED.length} more crossed over ${MARK_TOL} m outside a mark · median <b>${fmtStart(quantile(ts, 0.5))}</b> · `
    + `${early} crossed before the gun · median ${posText(quantile(us, 0.5))} · ${outside} within ${MARK_TOL} m outside a mark`;
  document.getElementById("posNote").textContent = `End bars: crossed up to ${MARK_TOL} m outside a mark (mark sway tolerance)`;
  const tLabel = i => i === 0 ? "more than 60 s early" : i === TIME_EDGES.length - 2 ? "more than 120 s late"
    : `${TIME_EDGES[i] >= 0 ? "+" : "−"}${Math.abs(TIME_EDGES[i])} to ${TIME_EDGES[i + 1] > 0 ? "+" : TIME_EDGES[i + 1] < 0 ? "−" : ""}${Math.abs(TIME_EDGES[i + 1])} s`;
  drawHist(document.getElementById("histTime"), TIME_EDGES, t => t.st.t, tLabel,
           [[4, "−30"], [7, "0"], [10, "+30"], [13, "+60"], [16, "+90"]], [7]);
  document.getElementById("posTitle").textContent = `Position on the line, ${SA} → ${SB} (${Math.round(LINE_M)} m)`;
  const pLabel = i => i === 0 ? `outside ${SA}` : i === POS_EDGES.length - 2 ? `outside ${SB}`
    : `${Math.round(POS_EDGES[i] * LINE_M)}–${Math.round(POS_EDGES[i + 1] * LINE_M)} m from ${SA}`;
  drawHist(document.getElementById("histPos"), POS_EDGES, t => t.st.u, pLabel,
           [[1, SA], [3.5, `${Math.round(LINE_M / 4)} m`], [6, `${Math.round(LINE_M / 2)} m`],
            [8.5, `${Math.round(LINE_M * 3 / 4)} m`], [11, SB]], [1, 11]);
}
const startsBox = document.getElementById("starts"), startsBtn = document.getElementById("startsBtn");
const setStarts = open => { startsBox.classList.toggle("open", open); startsBtn.setAttribute("aria-expanded", open);
                            save("sailing.starts", open ? "1" : ""); drawStarts(); };
startsBtn.onclick = () => setStarts(!startsBox.classList.contains("open"));
document.getElementById("startsClose").onclick = () => setStarts(false);

// ---- race picker -----------------------------------------------------------
const sel = document.getElementById("race");
[...years].reverse().forEach(y => {
  const group = document.createElement("optgroup");
  group.label = y;
  const ys = TRACKS.filter(t => t.year === y);
  group.appendChild(new Option(`All ${ys.length} races of ${y}`, "y" + y));
  [...ys].reverse().forEach(t => group.appendChild(new Option(
    `${nice(t.date)} · ${t.nm} nm · ${fmtDur(t.dur)}${t.fin ? "" : " (no finish)"}`, "t" + t.id)));
  sel.appendChild(group);
});
const step = d => { const n = sel.options.length; sel.selectedIndex = (sel.selectedIndex + d + n) % n; render(true); };
document.getElementById("prev").onclick = () => step(-1);
document.getElementById("next").onclick = () => step(1);
sel.onchange = () => render(true);
document.addEventListener("keydown", e => {
  if (e.target.tagName === "SELECT") return;
  if (e.key === "ArrowLeft") step(-1); else if (e.key === "ArrowRight") step(1);
});

let mode = "solid";
const modeBtns = [...document.querySelectorAll("#mode button")];
modeBtns.forEach(b => b.onclick = () => { mode = b.dataset.m; render(false); });

function load(key) { try { return localStorage.getItem(key); } catch (e) { return null; } }
function save(key, v) { try { localStorage.setItem(key, v); } catch (e) {} }
const savedRace = load("sailing.race"), savedMode = load("sailing.mode");
if (savedRace && [...sel.options].some(o => o.value === savedRace)) sel.value = savedRace; else sel.value = "t" + (TRACKS.length - 1);
if (savedMode && MODES[savedMode]) mode = savedMode;

// ---- rendering -------------------------------------------------------------
let shown = [];   // tracks currently drawn
function selected() {
  const v = sel.value;
  return v[0] === "y" ? TRACKS.filter(t => t.year === v.slice(1)) : [TRACKS[+v.slice(1)]];
}

function render(fit) {
  save("sailing.race", sel.value); save("sailing.mode", mode);
  shown = selected();
  const single = shown.length === 1;
  const hasHr = shown.some(t => t.h.some(h => h > 0));
  if (mode === "hr" && !hasHr) mode = "solid";
  modeBtns.forEach(b => { b.setAttribute("aria-pressed", b.dataset.m === mode); b.disabled = b.dataset.m === "hr" && !hasHr; });

  trackLayer.clearLayers();
  map.removeLayer(hoverDot);
  const weight = single ? 4 : 2.5;
  shown.forEach((t, k) => t.solid = single ? "#e6194b" : CATEGORICAL[k % CATEGORICAL.length]);

  // Shared color scale over the race portions of all shown tracks.
  let lo = 0, hi = 1;
  const M = MODES[mode];
  if (mode !== "solid") {
    const vals = [];
    shown.forEach(t => { for (let i = t.g; i < t.ll.length; i++) { const v = M.get(t, i); if (v != null) vals.push(v); } });
    vals.sort((a, b) => a - b);
    [lo, hi] = mode === "time" ? [0, vals[vals.length - 1] || 1] : [quantile(vals, 0.02), quantile(vals, 0.98)];
    if (hi <= lo) hi = lo + 1;
  }

  shown.forEach(t => {
    if (t.g > 0) L.polyline(t.ll.slice(0, t.g + 1), { color: PRE_GREY, weight, opacity: 0.8, renderer: preRenderer,
                                                     interactive: false }).addTo(trackLayer);
    if (mode === "solid") {
      L.polyline(t.ll.slice(t.g), { color: t.solid, weight, opacity: 0.9, interactive: false }).addTo(trackLayer);
      return;
    }
    // Merge consecutive segments that fall in the same color bin into one polyline.
    let run = [t.ll[t.g]], bin = null;
    const flush = () => { if (run.length > 1) L.polyline(run, { color: bin == null ? PRE_GREY : rampColor((bin + .5) / BINS),
                                                                weight, opacity: 0.95, interactive: false }).addTo(trackLayer); };
    for (let i = t.g; i < t.ll.length - 1; i++) {
      const a = M.get(t, i), b = M.get(t, i + 1);
      const v = a == null ? b : b == null ? a : (a + b) / 2;
      const nb = v == null ? null : Math.min(BINS - 1, Math.max(0, Math.floor((v - lo) / (hi - lo) * BINS)));
      if (nb !== bin && run.length > 1) { flush(); run = [t.ll[i]]; }
      bin = nb; run.push(t.ll[i + 1]);
    }
    flush();
  });

  // Legend
  const lg = document.getElementById("legend");
  if (mode === "solid") {
    lg.innerHTML = (single ? "" : `<div id="racelist">${shown.map(t =>
        `<div class="key" data-id="${t.id}"><span class="sw" style="background:${t.solid}"></span>${nice(t.date)}<span style="margin-left:auto;color:var(--muted)">${t.nm} nm${windMean(t) ? ` · ${windMean(t).kn.toFixed(0)} kn ${dirName(windMean(t).dir)}` : ""}</span></div>`).join("")}</div>`)
      + `<div class="key"><span class="sw" style="background:${PRE_GREY}"></span>Pre-start (warning → gun)</div>`;
    lg.querySelectorAll("#racelist .key").forEach(el => el.onclick = () => { sel.value = "t" + el.dataset.id; render(true); });
  } else {
    const stops = Array.from({ length: 11 }, (_, i) => rampColor(i / 10)).join(",");
    lg.innerHTML = `<div class="ramp" style="background:linear-gradient(to right,${stops})"></div>
      <div class="ticks"><span>${M.fmt(lo)}</span><span>${M.label} (${M.unit})</span><span>${M.fmt(hi)}</span></div>
      <div class="key"><span class="sw" style="background:${PRE_GREY}"></span>Pre-start (warning → gun)</div>`;
  }

  // Summary
  const s = document.getElementById("summary");
  if (single) {
    const t = shown[0], hrs = t.h.slice(t.g).filter(h => h > 0), sp = t.s.slice(t.g).map(v => v / 10);
    const avgKn = t.dur > 0 ? t.nm / (t.dur / 3600) : 0;
    s.innerHTML = `<b>${nice(t.date)}</b>${t.fin ? "" : " · <i>no finish crossing</i>"}<br>
      ${!t.st ? "No start crossing found<br>" : t.st.ok ? `Start ${fmtStart(t.st.t)}${t.st.t >= 0 ? " after gun" : ""} · ${posText(t.st.u)}<br>`
              : `Start line missed: crossed ${posText(t.st.u)} (${fmtStart(t.st.t)})<br>`}
      ${t.st && START_EXCLUDE.includes(t.year) ? `<i>${t.year} is left out of the start analysis</i><br>` : ""}
      ${t.nm} nm in ${fmtDur(t.dur)} · avg ${avgKn.toFixed(1)} kn · max ${Math.max(...sp).toFixed(1)} kn<br>
      ${hrs.length ? `HR avg ${Math.round(hrs.reduce((a, b) => a + b, 0) / hrs.length)} · max ${Math.max(...hrs)} bpm<br>` : ""}
      ${windMean(t) ? `Wind ${windText(windMean(t))}, gusts to ${windMean(t).gust.toFixed(0)} kn` : WIND ? "No wind data for this day" : ""}`;
  } else {
    const nm = shown.reduce((a, t) => a + t.nm, 0);
    s.innerHTML = `<b>${shown.length} races in ${shown[0].year}</b> · ${Math.round(nm)} nm<br>Click a race in the list to show it alone.`;
  }
  document.getElementById("info").innerHTML = "Hover over the track for details.";

  // Start-line crossing markers, labelled with the time after the gun; a crossing
  // too far outside the marks (a missed start line) gets a hollow red marker.
  shown.filter(t => t.st).forEach(t => {
    const txt = `${single ? "Start " : nice(t.date) + ": "}${fmtStart(t.st.t)}`
              + (t.st.ok ? "" : ` · missed line, ${posText(t.st.u)}`);
    L.circleMarker([t.st.p[0] / 1e5, t.st.p[1] / 1e5], { radius: single ? 6 : 4, color: t.st.ok ? "#000" : "#c0262d",
                                                        weight: 2, fillColor: "#fff", fillOpacity: t.st.ok ? 1 : 0 })
      .bindTooltip(txt, { permanent: single, direction: "left", offset: [-8, 0], className: "start-label" })
      .addTo(trackLayer);
  });
  drawStarts();
  drawWindChart(single ? shown[0] : null);
  drawWindArrow(single ? shown[0] : null);

  if (fit) {
    const b = L.latLngBounds(shown.flatMap(t => t.ll));
    map.fitBounds(b, { padding: [30, 30], maxZoom: 16 });
  }
}

// ---- hover: nearest point on the shown tracks ------------------------------
map.on("mousemove", e => {
  let best = null, bd = 15 * 15;
  const p = e.containerPoint;
  shown.forEach(t => t.ll.forEach((ll, i) => {
    const q = map.latLngToContainerPoint(ll), d = (q.x - p.x) ** 2 + (q.y - p.y) ** 2;
    if (d < bd) { bd = d; best = [t, i]; }
  }));
  const info = document.getElementById("info");
  if (!best) { map.removeLayer(hoverDot); if (windCursor) windCursor(null); return; }
  const [t, i] = best;
  hoverDot.setLatLng(t.ll[i]).addTo(map);
  const wo = windAt(t, t.t[i]);
  if (windCursor && shown.length === 1) windCursor(t.t[i]);
  const phase = i < t.g ? "pre-start" : "race";
  info.innerHTML = `${shown.length > 1 ? `<b>${nice(t.date)}</b><br>` : ""}<b>${fmtClock(t.t[i])}</b> from gun (${phase})<br>
    <b>${(t.s[i] / 10).toFixed(1)}</b> kn${t.h[i] ? ` · <b>${t.h[i]}</b> bpm` : ""}
    ${wo ? `<br>Wind ${(wo[1] / 10).toFixed(1)} kn from ${dirName(wo[3])} (${wo[3]}°)` : ""}`;
});
map.on("mouseout", () => { map.removeLayer(hoverDot); if (windCursor) windCursor(null); });
map.on("click", e => {
  // In year view, clicking a track shows that race alone.
  if (shown.length < 2) return;
  let best = null, bd = 15 * 15;
  shown.forEach(t => t.ll.forEach(ll => {
    const q = map.latLngToContainerPoint(ll), d = (q.x - e.containerPoint.x) ** 2 + (q.y - e.containerPoint.y) ** 2;
    if (d < bd) { bd = d; best = t; }
  }));
  if (best) { sel.value = "t" + best.id; render(true); }
});

render(true);
if (load("sailing.starts")) setStarts(true);
}

fetch("tracks.json")
  .then(r => { if (!r.ok) throw new Error(r.status + " " + r.statusText); return r.json(); })
  .then(startApp)
  .catch(e => { document.getElementById("info").textContent = "Could not load tracks.json: " + e.message; });
